import time

from .event_delegator import MPLCanvasEventDelegator

# Max interval (seconds) between two clicks on the same artist to count as a double-click.
_DOUBLE_CLICK_INTERVAL = 0.5

class ClickCatcher():
    """
        This class can be used to register matplotlib artists, which will
        fire the update_callback method when double-clicked. When registering
        the artist, an arbitrary object can be passed which is passed to the
        callback.
    """
    def __init__(self, plot_controller, update_callback=None):
        self.plot_controller = plot_controller
        self._canvas = plot_controller.canvas
        self._window = self._canvas.get_window()
        self._update_callback = update_callback
        self._last_pick_artist = None
        self._last_pick_time = 0.0
        self.connect()
        self._artists = {}

    def register_artist(self, artist, obj):
        self._artists[artist] = obj
        artist.set_picker(True)

    def _on_pick(self, event):
        if event.artist is None:
            return False
        # Matplotlib's event.mouseevent.dblclick is unreliable across backends
        # (some fire two separate picks on a double-click, both with dblclick=False).
        # Track picks manually: a second pick on the same artist within the interval
        # counts as a double-click.
        now = time.monotonic()
        is_dbl = (
            getattr(event.mouseevent, "dblclick", False) or
            (event.artist is self._last_pick_artist and
             (now - self._last_pick_time) <= _DOUBLE_CLICK_INTERVAL)
        )
        if is_dbl:
            self._last_pick_artist = None
            self._last_pick_time = 0.0
            obj = self._artists.get(event.artist, None)
            self._update_callback(obj)
        else:
            self._last_pick_artist = event.artist
            self._last_pick_time = now
        return False

    def connect(self):
        delegator = MPLCanvasEventDelegator.wrap_canvas(self._canvas)
        delegator.connect('pick_event', self._on_pick, first=True)

    def disconnect(self):
        delegator = MPLCanvasEventDelegator.wrap_canvas(self._canvas)
        delegator.disconnect('pick_event', self._on_pick)

    pass #end of class